functionCode.value:
for (const el of input){
    const cleanPlanMonth = el.PlanMonth?.replace(/^\|/, '');

    el.id = el.ScenarioID + '|;|' 
          + el.ProductType + '|;|' 
          + el.Region + '|;|' 
          + el.PlanYear + '|;|' 
          + cleanPlanMonth;
}

return input;
